async function fetchOpsHealth(){
 if(!isManager()||opsHealthLoading)return;
 opsHealthLoading=true;
 try{
  const {data:{session}}=await db.auth.getSession();if(!session?.access_token)throw Error('Sessão não disponível');
  const r=await fetch('/api/ops-health',{headers:{Authorization:`Bearer ${session.access_token}`},cache:'no-store'});
  if(!r.ok)throw Error(r.status===404?'Endpoint não publicado':`Diagnóstico indisponível (${r.status})`);
  const body=await r.json();opsHealth=body;
 }catch(e){opsHealth={error:e.message||'Indisponível'}}
 finally{opsHealthLoading=false; if(['command','integrations'].includes(currentTab)&&document.querySelector('#content'))showTab()}
}
function showIntegrations(){
 const el=document.querySelector('#content');if(!isManager())return;
 const h=opsHealth;
 const state=(o)=>o?.available===true?'<span class="pill green">Disponível</span>':o?.available===false?'<span class="pill orange">Indisponível</span>':'<span class="pill purple">Não verificado</span>';
 const last=h?.last_received_at?new Date(h.last_received_at).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'}):'Não disponível';
 const eventCount=h?.inbox?.count;
 const automation=h?.automation?.available?(h.automation.enabled?'Ativada no banco':'Pausada no banco'):'Não verificada';
 el.innerHTML=`<section class="integrationHero"><span class="eyebrow">BR WHATS → VERCEL → SUPABASE</span><h2>Monitoramento de integrações</h2><p>Resumo técnico seguro para a gestão, sem exibir mensagens, telefones ou segredos.</p><button class="outline" id="recheckHealth" ${opsHealthLoading?'disabled':''}>↻ Consultar servidor</button></section>${h?.error?`<div class="errorBanner">${esc(h.error)}. Confira se api/ops-health.js foi publicado e se o serviço tem as variáveis do Supabase.</div>`:''}<div class="integrationGrid"><article class="integrationStat"><span>Recebimento de eventos</span><b>${eventCount===undefined?'—':eventCount}</b>${state(h?.inbox)}<small>Registros na inbox; não equivalem a clientes únicos.</small></article><article class="integrationStat"><span>Eventos processados</span><b>${h?.processed?.count??'—'}</b>${state(h?.processed)}<small>Histórico de processamento disponível no banco.</small></article><article class="integrationStat"><span>Automação comercial</span><b class="integrationText">${esc(automation)}</b>${state(h?.automation)}<small>Configuração lida no Supabase, sem botões de alteração.</small></article><article class="integrationStat"><span>Sincronizações auditadas</span><b>${h?.sync_audit?.count??'—'}</b>${state(h?.sync_audit)}<small>Eventos de atribuição/agendamento realmente sincronizados.</small></article></div><div class="section integrationDetail"><div class="sectionhead"><h2>Estado atual</h2><span class="count">Última mensagem: ${esc(last)}</span></div><div class="healthTimeline"><div><span class="signalDot ${h?.inbox?.available?'good':'neutral'}"></span><b>Webhook de entrada</b><small>Recebe eventos assinados da BR Whats e os armazena na inbox.</small></div><div><span class="signalDot ${h?.processed?.available?'good':'neutral'}"></span><b>Processamento comercial</b><small>Gera leads conforme regras quando habilitado no backend; não confirma vendedor da Camila.</small></div><div><span class="signalDot warn"></span><b>Atribuição e agenda</b><small>Aguardando evento/API de transferência e agendamento da BR Whats para sincronização fiel.</small></div></div></div><div class="callout">O IVS é capaz de <b>receber mensagens</b>, mas isso não comprova o sincronismo do <b>responsável ou horário marcado pela Camila</b>. As vendedoras devem conferir essas duas informações antes de agir.</div>`;
 el.querySelector('#recheckHealth').onclick=()=>fetchOpsHealth();
}
function modal(title,body,submit,afterSave){const d=document.querySelector('#modal');document.querySelector('#modalContent').innerHTML=`<h2>${esc(title)}</h2><p>Preencha os dados e salve para sincronizar com o Supabase.</p><div class="inlineForm">${body}</div>`;const form=document.querySelector('#modalForm');form.onsubmit=async e=>{e.preventDefault();const btn=document.querySelector('#submitModal');btn.disabled=true;try{await submit(new FormData(form));await load();if(afterSave)afterSave();d.close();layout();notify('Registro salvo e sincronizado')}catch(e){errorMessage(e)}finally{btn.disabled=false}};document.querySelector('#cancelModal').onclick=()=>d.close();d.showModal()}
function field(name,label,value='',type='text',extra=''){return `<div class="field"><label>${esc(label)}</label><input name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`}
function selectField(name,label,options,value){return `<div class="field"><label>${esc(label)}</label><select name="${name}">${options.map(o=>typeof o==='string'?`<option ${o===value?'selected':''} value="${esc(o)}">${esc(o)}</option>`:`<option value="${o.id}" ${o.id===value?'selected':''}>${esc(o.name)}</option>`).join('')}</select></div>`}
function textField(name,label,value=''){return `<div class="field wide"><label>${esc(label)}</label><textarea name="${name}">${esc(value)}</textarea></div>`}
function openLead(l){const owners=isManager()?people.filter(p=>p.active):[me];const body=field('name','Nome do cliente',l?.name,'text','required')+field('phone','Telefone',l?.phone)+field('need','Necessidade',l?.need)+selectField('owner_id','Vendedor responsável',owners,l?.owner_id||user.id)+selectField('status','Etapa',statusValues,l?.status||'Novo lead')+selectField('priority','Prioridade',priorValues,l?.priority||'Média')+field('next_action','Próxima ação',l?.next_action)+field('due_date','Data limite',l?.due_date,'date')+field('expected_value','Valor de orçamento (R$)',l?.expected_value||0,'number','min="0" step="0.01"')+selectField('consent','Permite contato?', ['Verificar','Sim','Não'],l?.consent||'Verificar')+textField('notes','Observações',l?.notes);modal(l?'Editar oportunidade':'Nova oportunidade',body,async f=>{const data={name:f.get('name').trim(),phone:f.get('phone'),need:f.get('need'),owner_id:f.get('owner_id'),status:f.get('status'),priority:f.get('priority'),next_action:f.get('next_action'),due_date:f.get('due_date')||null,expected_value:Number(f.get('expected_value'))||0,consent:f.get('consent'),notes:f.get('notes')};if(l){const r=await db.from('leads').update(data).eq('id',l.id).select();if(r.error)throw r.error;if(!r.data?.length)throw Error('Alteração negada.')}else{const r=await db.from('leads').insert({...data,created_by:user.id});if(r.error)throw r.error}})}
function openActivity(id){const l=leads.find(x=>x.id===id);if(l.consent==='Não'){errorMessage('Cliente não permite contatos. Não realize prospecção sem nova autorização.');return}modal('Registrar contato · '+l.name,selectField('channel','Canal',['Ligação','WhatsApp','Presencial','Outro'],'Ligação')+selectField('kind','Tipo',['Primeiro contato','Recontato','Confirmação','Recuperação de orçamento','Pós-venda','Outro'],'Recontato')+field('outcome','Resultado','','text','required')+field('next_action','Próxima ação',l.next_action)+field('next_due','Próximo prazo',l.due_date,'date'),async f=>{const r=await db.from('activities').insert({lead_id:id,user_id:user.id,channel:f.get('channel'),kind:f.get('kind'),outcome:f.get('outcome'),next_action:f.get('next_action'),next_due:f.get('next_due')||null});if(r.error)throw r.error;const u=await db.from('leads').update({next_action:f.get('next_action'),due_date:f.get('next_due')||null}).eq('id',id);if(u.error)throw u.error})}
function openAppointment(id){
 const l=leads.find(x=>x.id===id);
 const existing=appointments.filter(a=>a.lead_id===id&&['Pendente','Confirmado'].includes(a.status)).sort((a,b)=>b.created_at.localeCompare(a.created_at))[0];
 if(existing){openAppointmentStatus(existing);notify('Existe um agendamento ativo: edite o mesmo registro para evitar duplicações.');return}
 const value=localInputTime(new Date(Date.now()+3600000).toISOString());
 modal('Agendar · '+l.name,field('when','Data e horário (Piracicaba)',value,'datetime-local','required')+selectField('status','Situação',['Pendente','Confirmado'],'Pendente')+textField('notes','Observações'),async f=>{
  // Also check the current database state to prevent accidentally duplicating a pending appointment.
  const check=await db.from('appointments').select('id,status').eq('lead_id',id).in('status',['Pendente','Confirmado']).limit(1);
  if(check.error)throw check.error;if(check.data.length)throw Error('Já existe um agendamento pendente ou confirmado para este cliente. Atualize a agenda antes de criar outro.');
  const r=await db.from('appointments').insert({lead_id:id,owner_id:l.owner_id,scheduled_at:saoPauloIso(f.get('when')),status:f.get('status'),notes:f.get('notes')}).select('id');
  if(r.error)throw r.error;if(!r.data?.length)throw Error('Agendamento não confirmado pelo banco.');
  const idAgendamento=r.data[0].id;
  const confirmado=await db.from('appointments').select('id,lead_id,owner_id,scheduled_at,status').eq('id',idAgendamento).maybeSingle();
  if(confirmado.error)throw Error('Agendamento criado, mas houve um problema para consultá-lo: '+confirmado.error.message);
  if(!confirmado.data)throw Error('O agendamento foi criado, mas está invisível para este usuário. Confira a política RLS de leitura e o responsável pelo agendamento no Supabase. ID: '+idAgendamento);
 },()=>{currentTab='appointments'});
}
function openAppointmentStatus(a){
 modal('Atualizar / reagendar',field('when','Data e horário (Piracicaba)',localInputTime(a.scheduled_at),'datetime-local','required')+selectField('status','Situação',appointmentValues,a.status)+textField('notes','Observações',a.notes),async f=>{
  const newStatus=f.get('status');const newDate=saoPauloIso(f.get('when'));
  if(['Pendente','Confirmado'].includes(newStatus)){
   const check=await db.from('appointments').select('id').eq('lead_id',a.lead_id).in('status',['Pendente','Confirmado']).neq('id',a.id).limit(1);
   if(check.error)throw check.error;if(check.data.length)throw Error('Este cliente já tem outro agendamento ativo. Resolva-o antes de reativar este.');
  }
  const r=await db.from('appointments').update({scheduled_at:newDate,status:newStatus,notes:f.get('notes')}).eq('id',a.id).select('id,status,lead_id,scheduled_at');
  if(r.error)throw r.error;if(!r.data?.length)throw Error('O Supabase não autorizou a atualização do agendamento. Confira as permissões.');
  if(r.data[0].status!==newStatus)throw Error('O status retornado não corresponde à alteração solicitada.');
  if(newStatus==='Compareceu'){
   const lead=leads.find(l=>l.id===a.lead_id);
   if(lead&&!closed(lead)&&lead.status!=='Compareceu'){
    const u=await db.from('leads').update({status:'Compareceu'}).eq('id',a.lead_id).select('id,status');
    if(u.error||!u.data?.length)throw Error('O agendamento foi salvo, mas a etapa do lead não foi atualizada. '+(u.error?.message||''));
   }
  }
 });
}
function openSale(id){const l=leads.find(x=>x.id===id);modal('Registrar venda · '+l.name,field('amount','Valor vendido (R$)','','number','required min="0" step="0.01"')+field('sold_at','Data da venda',day(),'date','required')+textField('notes','Observações'),async f=>{const r=await db.from('sales').insert({lead_id:id,seller_id:user.id,amount:Number(f.get('amount')),sold_at:f.get('sold_at'),notes:f.get('notes')});if(r.error)throw r.error})}
async function refresh(){try{await load();layout();if(isManager()&&['command','integrations'].includes(currentTab))fetchOpsHealth()}catch(e){errorMessage(e)}}
async function init(){if(!db){renderLogin();return}const {data:{session}}=await db.auth.getSession();user=session?.user||null;if(user){try{await load();layout();if(isManager()&&['command','integrations'].includes(currentTab))fetchOpsHealth()}catch(e){renderLogin(e.message)}}else renderLogin();db.auth.onAuthStateChange((event,session)=>{if(event==='SIGNED_OUT'){user=null;me=null;renderLogin()}else if(event==='SIGNED_IN'&&session?.user?.id!==user?.id){user=session.user;setTimeout(()=>refresh(),0)}})}
init();